export interface Customer {
  yearsWithMHPCO: number;
}

export interface QuoteItem {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface QuoteStep {
  op: 'quote';
  items: QuoteItem[];
}

export interface Damage {
  itemType: string;
  amount: number;
}

export interface ClaimStep {
  op: 'claim';
  policy: number;
  incident: { cause: string; damages: Damage[] };
}

export type Step = QuoteStep | ClaimStep;

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export type StepResult =
  | { premium: number }
  | { payout: number; remainingCap: number };

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE = 0.1;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
};

const COMPONENT_BASE_PREMIUM = 25;
const COMPONENT_TYPES = ['rune', 'moonstone'];

function isComponent(type: string): boolean {
  return COMPONENT_TYPES.includes(type);
}

function basePremiumOf(item: QuoteItem): number {
  return isComponent(item.type)
    ? COMPONENT_BASE_PREMIUM
    : BASE_PREMIUMS[item.type];
}

function quotePremium(items: QuoteItem[]): number {
  const policyBase = items.reduce((sum, item) => sum + basePremiumOf(item), 0);
  return policyBase + policyBase * FIRST_INSURANCE_SURCHARGE + PROCESSING_FEE;
}

export function runScenario(scenario: Scenario): { results: StepResult[] } {
  const results = scenario.steps.map((step) => ({
    premium: quotePremium((step as QuoteStep).items),
  }));
  return { results };
}

